// Comprehensive loader test: uses several datatypes; skips the header;
//                            handles missing/extra fields; handles quotes, commas, newlines
@Test
public void load() throws IOException, ParseException {
    String schema = "i: int, l: long, f: float, d: double, c: chararray, b: bytearray";
    pig.registerQuery("data = load '" + dataDir + testFile + "' " + "using org.apache.pig.piggybank.storage.CSVExcelStorage(',', 'YES_MULTILINE', 'UNIX', 'SKIP_INPUT_HEADER') " + "AS (" + schema + ");");
    Iterator<Tuple> data = pig.openIterator("data");
    String[] expected = { // a header in csv_excel_data.csv should be skipped due to 'SKIP_INPUT_HEADER' being set in test_csv_storage_load.pig
    // basic data types
    "(1,10,2.718,3.14159,qwerty,uiop)", // missing fields at end
    "(1,10,2.718,3.14159,,)", // missing field in the middle
    "(1,10,,3.15159,,uiop)", // extra field (input data has "moose" after "uiop")
    "(1,10,,3.15159,,uiop)", // quoted regular fields (2.718, qwerty, and uiop in quotes)
    "(1,,2.718,,qwerty,uiop)", // newlines in quotes
    "(1,,,,\nqwe\nrty, uiop)", // After LOAD \r => \n (PIG-4213)
    "(1,10,2.718,3.14159,abc\ndef,uiop)", // commas in quotes
    "(1,,,,qwe,rty,uiop)", // quotes in quotes
    "(1,,,,q\"wert\"y, uiop)", // quotes in quotes at the end of a line
    "(1,,,,qwerty,u\"io\"p)" };
    Assert.assertEquals(StringUtils.join(expected, "\n"), StringUtils.join(data, "\n"));
}

