@Test
public void testWriteToDB() throws IOException, InterruptedException, ParseException {
    String insertQuery = "insert into ttt (id, name, ratio, dt) values (?,?,?,?)";
    pigServer.setBatchOn();
    String dbStore = "org.apache.pig.piggybank.storage.DBStorage('" + driver + "', '" + Util.encodeEscape(dbUrl) + "', '" + insertQuery + "');";
    pigServer.registerQuery("A = LOAD '" + INPUT_FILE + "' as (id:int, fruit:chararray, ratio:double, dt : datetime);");
    pigServer.registerQuery("STORE A INTO 'dummy' USING " + dbStore);
    ExecJob job = pigServer.executeBatch().get(0);
    try {
        while (!job.hasCompleted()) Thread.sleep(1000);
    } catch (InterruptedException ie) {
        // ignore
    }
    assertNotSame("Failed: " + job.getException(), job.getStatus(), ExecJob.JOB_STATUS.FAILED);
    Connection con = null;
    String selectQuery = "select id, name, ratio, dt from ttt order by name";
    try {
        con = DriverManager.getConnection(dbUrl, user, password);
    } catch (SQLException sqe) {
        throw new IOException("Unable to obtain database connection for data verification", sqe);
    }
    try {
        PreparedStatement ps = con.prepareStatement(selectQuery);
        ResultSet rs = ps.executeQuery();
        int expId = 100;
        String[] expNames = { "apple", "banana", "orange" };
        double[] expRatios = { 1.0, 1.1, 2.0 };
        DateFormat df = new SimpleDateFormat("yyyy-MM-dd");
        Date[] expDates = { new Date(df.parse("2008-01-01").getTime()), new Date(df.parse("2008-03-01").getTime()), new Date(df.parse("2008-02-01").getTime()) };
        for (int i = 0; i < 4; i++) {
            rs.next();
            //Need to check for nulls explicitly.
            if (i == 0) {
                //Id
                rs.getInt(1);
                assertTrue(rs.wasNull());
                //Name
                rs.getString(2);
                assertTrue(rs.wasNull());
                //Ratio
                rs.getDouble(3);
                assertTrue(rs.wasNull());
                //Date
                rs.getDate(4);
                assertTrue(rs.wasNull());
            } else {
                assertEquals("Id mismatch", expId, rs.getInt(1));
                assertEquals("Name mismatch", expNames[i - 1], rs.getString(2));
                assertEquals("Ratio mismatch", expRatios[i - 1], rs.getDouble(3), 0.0001);
                assertEquals("Date mismatch", expDates[i - 1], rs.getDate(4));
            }
        }
    } catch (SQLException sqe) {
        throw new IOException("Unable to read data from database for verification", sqe);
    }
}

