@Test
public void testByteArrayAlphabeticalOrderingByLength() throws Exception {
    // making sure we order as
    // '1'
    // '2'
    // '22'
    // '222' and repeats...
    // If compare includes the header, order suddenly changes when header
    // changes from INTEGER_INSHORT to INTEGER.
    // Here, we're making sure that doesn't happen.
    //
    for (int i = BinInterSedes.UNSIGNED_BYTE_MAX - 3; i < BinInterSedes.UNSIGNED_BYTE_MAX + 3; i++) {
        DataByteArray dba1 = createRepeatedByteArray((byte) '2', i);
        DataByteArray dba2 = createRepeatedByteArray((byte) '2', i + 1);
        assertTrue("ByteArray order changed at UNSIGNED_BYTE_MAX boundary", compareTwoObjectsAsNullableBytesWritables(dba1, dba2) < 0);
    }
    for (int i = BinInterSedes.UNSIGNED_SHORT_MAX - 3; i < BinInterSedes.UNSIGNED_SHORT_MAX + 3; i++) {
        DataByteArray dba1 = createRepeatedByteArray((byte) '2', i);
        DataByteArray dba2 = createRepeatedByteArray((byte) '2', i + 1);
        assertTrue("ByteArray order changed at UNSIGNED_SHORT_MAX boundary", compareTwoObjectsAsNullableBytesWritables(dba1, dba2) < 0);
    }
}

@Test
public void testLongByteArrays() throws Exception {
    for (int length : new int[] { BinInterSedes.UNSIGNED_BYTE_MAX + 50, BinInterSedes.UNSIGNED_SHORT_MAX + 50 }) {
        // To make sure that offset & length are set correctly for
        // BinInterSedes.SMALLBYTEARRAY and BinInterSedes.BYTEARRAY,
        // create a long bytearray and compare with first or last byte changed
        byte[] ba1 = new byte[length];
        byte[] ba2 = new byte[length];
        Arrays.fill(ba1, 0, length, (byte) 'a');
        Arrays.fill(ba2, 0, length, (byte) 'a');
        //changing only the last byte
        ba2[length - 1] = 'b';
        assertTrue("ByteArray with length: " + length + " compare failed with the last byte", compareTwoObjectsAsNullableBytesWritables(new DataByteArray(ba1), new DataByteArray(ba2)) != 0);
        //setting back
        ba2[length - 1] = 'a';
        //now changing the first byte
        ba2[0] = 'b';
        assertTrue("ByteArray with length: " + length + " compare failed with the first byte", compareTwoObjectsAsNullableBytesWritables(new DataByteArray(ba1), new DataByteArray(ba2)) != 0);
    }
}

