    checkItemsLT(outBag, 1, 10);
}

@Test
public void testTopAlgebraic() throws IOException {
    // initial results
    Tuple init = (new TOP.Initial("DESC")).exec(inputTuple_);
    // intermediate results
    DataBag intermedBag = bagFactory_.newDefaultBag();
    Tuple intermedInput = tupleFactory_.newTuple(intermedBag);
    intermedBag.add(init);
    Tuple intermedOutput = (new TOP.Intermed("DESC")).exec(intermedInput);
    checkItemsGT((DataBag) intermedOutput.get(2), 1, 89);
    // final result
    DataBag finalInputBag = bagFactory_.newDefaultBag();
    Tuple finalInput = tupleFactory_.newTuple(finalInputBag);
    finalInputBag.add(intermedOutput);
    DataBag outBag = (new TOP.Final("DESC")).exec(finalInput);
    assertEquals(outBag.size(), 10L);
    checkItemsGT(outBag, 1, 89);
    // initial results
    init = (new TOP.Initial("ASC")).exec(inputTuple_);
    // intermediate results
    intermedBag = bagFactory_.newDefaultBag();
    intermedInput = tupleFactory_.newTuple(intermedBag);
    intermedBag.add(init);
    intermedOutput = (new TOP.Intermed("ASC")).exec(intermedInput);
    checkItemsLT((DataBag) intermedOutput.get(2), 1, 10);
    // final result
    finalInputBag = bagFactory_.newDefaultBag();
    finalInput = tupleFactory_.newTuple(finalInputBag);
    finalInputBag.add(intermedOutput);
    outBag = (new TOP.Final("ASC")).exec(finalInput);
    assertEquals(outBag.size(), 10L);
    checkItemsLT(outBag, 1, 10);
}

@Test
public /* Test that the simple data types convert properly in a tuple context */
void testSimpleTypes() throws Exception {
    Utf8StorageConverter converter = new Utf8StorageConverter();
    String schemaString = "a:int, b:long, c:float, d:double, e:chararray, f:bytearray, g:boolean, h:biginteger, i:bigdecimal, j:datetime";
    String dataString = "(1,2,3.0,4.0,five,6,true,12345678901234567890,1234567890.0987654321,2007-04-05T14:30Z)";
    ResourceSchema.ResourceFieldSchema rfs = new ResourceFieldSchema(new FieldSchema("schema", Utils.getSchemaFromString(schemaString)));
    Tuple result = converter.bytesToTuple(dataString.getBytes(), rfs);
    assertEquals(10, result.size());
    assertEquals(new Integer(1), result.get(0));
    assertEquals(new Long(2L), result.get(1));
    assertEquals(new Float(3.0f), result.get(2));
    assertEquals(new Double(4.0), result.get(3));
    assertEquals("five", result.get(4));
    assertEquals(new DataByteArray(new byte[] { (byte) '6' }), result.get(5));
    assertEquals(new Boolean(true), result.get(6));
    assertEquals(new BigInteger("12345678901234567890"), result.get(7));
    assertEquals(new BigDecimal("1234567890.0987654321"), result.get(8));
    assertEquals(new DateTime("2007-04-05T14:30Z", DateTimeZone.UTC), result.get(9));
}

