@Test
public void testPythonUDF__allTypes() throws Exception {
    pigServerLocal = new PigServer(Util.getLocalTestMode());
    String[] pythonScript = { "# -*- coding: utf-8 -*-", "from __future__ import print_function", "from pig_util import outputSchema", "import sys", "", "@outputSchema('tuple_output:tuple(nully:chararray, inty:int, longy:long, floaty:float, doubly:double, chararrayy:chararray, utf_chararray_basic_string:chararray, utf_chararray_unicode:chararray, bytearrayy:bytearray)')", "def get_tuple_output():", "    result = (None, 32, 1000000099990000, 32.0, 3200.1234678509, 'Some String', b'Hello\\u2026Hello', u'Hello\\u2026Hello', b'Some Byte Array')", "    return result", "", "@outputSchema('tuple_output:tuple(nully:chararray, inty:int, longy:long, floaty:float, doubly:double, chararrayy:chararray, utf_chararray_basic_string:chararray, utf_chararray_unicode:chararray, bytearrayy:bytearray)')", "def crazy_tuple_identity(ct):", "    print(ct)", "    return ct", "", "@outputSchema('mappy:map[]')", "def add_map():", "    return {u'Weird\\u2026Name' : u'Weird \\u2026 Value',", "            'SomeNum'          : 32,", "            'Simple Name'      : 'Simple Value' }", "", "", "@outputSchema('silly:chararray')", "def silly(silly_word):", "    print(silly_word.encode('utf-8'))", "    return silly_word", "", "", "@outputSchema('final_output:bag{t:tuple(user_id:chararray,age:int,tuple_output:tuple(nully:chararray,inty:int,longy:long,floaty:float,doubly:double,chararrayy:chararray,utf_chararray_basic_string:chararray,utf_chararray_unicode:chararray,bytearrayy:bytearray),mappy:map[],silly:chararray)}')", "def bag_identity(bag):", "    return bag" };
    Util.createLocalInputFile("allfile.py", pythonScript);
    Data data = resetData(pigServerLocal);
    Tuple t0 = tf.newTuple(2);
    t0.set(0, "user1");
    t0.set(1, 10);
    Tuple t1 = tf.newTuple(2);
    t1.set(0, "user2");
    t1.set(1, 11);
    data.set("userTuples", "user_id:chararray,age:int", t0, t1);
    pigServerLocal.registerQuery("REGISTER 'allfile.py' USING streaming_python AS pf;");
    pigServerLocal.registerQuery("users = LOAD 'userTuples' USING mock.Storage();");
    pigServerLocal.registerQuery("crazy_tuple = FOREACH users GENERATE user_id, age, pf.get_tuple_output();");
    pigServerLocal.registerQuery("crazy_tuple_fun = FOREACH crazy_tuple GENERATE user_id, age, pf.crazy_tuple_identity(tuple_output);");
    pigServerLocal.registerQuery("crazy_tuple_with_map = FOREACH crazy_tuple_fun GENERATE user_id, age, tuple_output, pf.add_map(), pf.silly('\u2026');");
    pigServerLocal.registerQuery("crazy_group = GROUP crazy_tuple_with_map BY (age);");
    pigServerLocal.registerQuery("out = FOREACH crazy_group GENERATE group, pf.bag_identity(crazy_tuple_with_map);");
    pigServerLocal.registerQuery("STORE out INTO 'all_out' USING mock.Storage();");
    List<Tuple> out = data.get("all_out");
    /*
         * Expected output for first tuple.
         * (10,
         * {(user1,10,(,32,1000000099990000,32.0,3200.12346785,Some String,Hello\u2026Hello,Hello\u2026Hello,Some Byte Array),
         *   [Simple Name#Simple Value,SomeNum#32,Weird\u2026Name#Weird \u2026 Value],\u2026)
         * })
         */
    //Get Bag
    DataBag bag = (DataBag) out.get(0).get(1);
    assertEquals(1, bag.size());
    //Get First Bag Tuple
    Tuple innerTuple = bag.iterator().next();
    assertEquals(5, innerTuple.size());
    LOG.info("tuple: " + innerTuple);
    //Check fields in innermost tuple
    assertEquals("Hello\\u2026Hello", ((Tuple) innerTuple.get(2)).get(6));
    assertEquals("Hello\u2026Hello", ((Tuple) innerTuple.get(2)).get(7));
    assertTrue(((Map<String, Object>) innerTuple.get(3)).containsKey("Weird\u2026Name"));
    assertEquals("Weird \u2026 Value", ((Map<String, Object>) innerTuple.get(3)).get("Weird\u2026Name"));
    assertEquals("\u2026", innerTuple.get(4));
}

