@Test
public void testRelationAliasInNestedForeachWhereUnspecified() throws Exception {
    Data data = resetData(pigServer);
    List<Tuple> values = Lists.newArrayList();
    for (int i = 0; i < 10; i++) {
        values.add(tuple(i % 3 == 0 ? null : "a", "b"));
    }
