/**
 * Tests all combination where:
 * sync marker is {x, y, 4}
 * data is {127, -2, 2, z, x, y, 4, 1, 2, 3}
 * x,y,z in [-128,127]
 * This means that a sync marker has to be found in all iterations (total=16,777,216)
 * @throws Exception
 */
@Test
public void testPrefixSyncMarkers() throws Exception {
    long defaultInterval = PigConfiguration.PIG_INTERSTORAGE_SYNCMARKER_INTERVAL_DEFAULT;
    ClassLoader classloader = PigContext.getClassLoader();
    Class<?> klazz;
    try {
        klazz = PigContext.resolveClassName("org.mockito.internal.util.reflection.Whitebox");
    } catch (Exception ex) {
        klazz = PigContext.resolveClassName("org.apache.hadoop.test.Whitebox");
    }
    if (klazz == null) {
        throw new Exception("No Whitebox class found.");
    }
    Method method = klazz.getMethod("setInternalState", Object.class, String.class, Object.class);
    for (int b0 = -128; b0 <= 127; b0++) {
        for (int b1 = -128; b1 <= 127; b1++) {
            for (int b2 = -128; b2 <= 127; b2++) {
                byte[] syncMarker = new byte[] { (byte) b0, (byte) b1, (byte) 4 };
                byte[] data = new byte[] { 127, -1, 2, (byte) b2, (byte) b0, (byte) b1, 4, 1, 2, 3 };
                ByteArrayInputStream bi = new ByteArrayInputStream(data);
                BufferedPositionedInputStream bpi = new BufferedPositionedInputStream(bi);
                InterRecordReader reader = new InterRecordReader(syncMarker.length, defaultInterval);
                method.invoke(null, reader, "syncMarker", syncMarker);
                method.invoke(null, reader, "end", data.length);
                method.invoke(null, reader, "in", bpi);
                try {
                    boolean ret = reader.skipUntilMarkerOrSplitEndOrEOF();
                    assertTrue("Marker should have been found: " + "marker: " + Arrays.toString(syncMarker) + " , data: " + Arrays.toString(data), ret);
                } finally {
                    bpi.close();
                }
            }
        }
    }
}

/**
 * Tests the blacklist filter. We blacklist "set" and make sure this test
 * throws a {@link FrontendException}
 *
 * @throws Exception
 */
@Test
public void testBlacklist() throws Exception {
    try {
        ctx.getProperties().setProperty(PigConfiguration.PIG_BLACKLIST, "set");
        PigServer pigServer = new PigServer(ctx);
        Data data = resetData(pigServer);
        data.set("foo", tuple("a", 1, "b"), tuple("b", 2, "c"), tuple("c", 3, "d"));
        StringBuilder script = new StringBuilder();
        script.append("set io.sort.mb 1000;").append("A = LOAD 'foo' USING mock.Storage() AS (f1:chararray,f2:int,f3:chararray);").append("B = order A by f1,f2,f3 DESC;").append("STORE B INTO 'bar' USING mock.Storage();");
        pigServer.registerScript(IOUtils.toInputStream(script));
