public void testTimeZone() throws IOException {
    // Usually set through "pig.datetime.default.tz"
    String defaultDTZ = "+03:00";
    DateTimeZone.setDefault(DateTimeZone.forID(defaultDTZ));
    String[] inputs = { "1970-01-01T00:00:00.000-08:00", "1970-01-01T00:00", "1970-01-01T00", "1970-01-01T", "1970-01T", "1970T", "1970-01-01T00:00-08:00", "1970-01-01T00-05:00", "1970-01-01T-08:00", "1970-01T-08:00", //"1970T+8:00", //Invalid format
    "1970-01-01", "1970-01", "1970" };
    String[] expectedDTZOutputs = { "-08:00", defaultDTZ, defaultDTZ, defaultDTZ, defaultDTZ, defaultDTZ, "-08:00", "-05:00", "-08:00", "-08:00", defaultDTZ, defaultDTZ, defaultDTZ };
    String[] expectedDTOutputs = { "1970-01-01T00:00:00.000-08:00", "1970-01-01T00:00:00.000" + defaultDTZ, "1970-01-01T00:00:00.000" + defaultDTZ, "1970-01-01T00:00:00.000" + defaultDTZ, "1970-01-01T00:00:00.000" + defaultDTZ, "1970-01-01T00:00:00.000" + defaultDTZ, "1970-01-01T00:00:00.000-08:00", "1970-01-01T00:00:00.000-05:00", "1970-01-01T00:00:00.000-08:00", "1970-01-01T00:00:00.000-08:00", "1970-01-01T00:00:00.000" + defaultDTZ, "1970-01-01T00:00:00.000" + defaultDTZ, "1970-01-01T00:00:00.000" + defaultDTZ };
    for (int i = 0; i < inputs.length; i++) {
        DateTimeZone dtz = ToDate.extractDateTimeZone(inputs[i]);
        assertEquals(expectedDTZOutputs[i], dtz.toString());
