                    lt.setValue(inpf1);
                    rt.setValue(0.0f);
                    resf = op.getNextFloat();
                    assertEquals(null, (Float) resf.result);
                    break;
                }
            case DataType.INTEGER:
                {
                    Integer inpi1 = r.nextInt();
                    Integer inpi2 = r.nextInt();
                    lt.setValue(inpi1);
                    rt.setValue(inpi2);
                    Result resi = op.getNextInteger();
                    Integer expected = new Integer(inpi1 / inpi2);
                    assertEquals(expected, (Integer) resi.result);
                    // test with null in lhs
                    lt.setValue(null);
                    rt.setValue(inpi2);
                    resi = op.getNextInteger();
                    assertEquals(null, (Integer) resi.result);
                    // test with null in rhs
                    lt.setValue(inpi1);
                    rt.setValue(null);
                    resi = op.getNextInteger();
                    assertEquals(null, (Integer) resi.result);
                    // test divide by 0
                    lt.setValue(inpi1);
                    rt.setValue(0);
                    resi = op.getNextInteger();
                    assertEquals(null, (Integer) resi.result);
                    break;
                }
            case DataType.LONG:
                {
                    Long inpl1 = r.nextLong();
                    Long inpl2 = r.nextLong();
                    lt.setValue(inpl1);
                    rt.setValue(inpl2);
                    Result resl = op.getNextLong();
                    Long expected = new Long(inpl1 / inpl2);
                    assertEquals(expected, (Long) resl.result);
                    // test with null in lhs
                    lt.setValue(null);
                    rt.setValue(inpl2);
                    resl = op.getNextLong();
                    assertEquals(null, (Long) resl.result);
                    // test with null in rhs
                    lt.setValue(inpl1);
                    rt.setValue(null);
                    resl = op.getNextLong();
                    assertEquals(null, (Long) resl.result);
                    // test divide by 0
                    lt.setValue(inpl1);
                    rt.setValue(0l);
                    resl = op.getNextLong();
                    assertEquals(null, (Long) resl.result);
                    break;
                }
            case DataType.BIGDECIMAL:
                {
                    MathContext mc = new MathContext(Divide.BIGDECIMAL_MINIMAL_SCALE, RoundingMode.HALF_UP);
                    BigDecimal inpf1 = new BigDecimal(r.nextDouble(), mc);
                    BigDecimal inpf2 = new BigDecimal(r.nextDouble(), mc);
                    lt.setValue(inpf1);
                    rt.setValue(inpf2);
                    Result resf = op.getNextBigDecimal();
                    BigDecimal expected = inpf1.divide(inpf2, 2 * Divide.BIGDECIMAL_MINIMAL_SCALE + 1, RoundingMode.HALF_UP);
                    assertEquals(expected, (BigDecimal) resf.result);
                    // test with null in lhs
                    lt.setValue(null);
                    rt.setValue(inpf2);
                    resf = op.getNextBigDecimal();
                    assertEquals(null, (BigDecimal) resf.result);
                    // test with null in rhs
                    lt.setValue(inpf1);
                    rt.setValue(null);
                    resf = op.getNextBigDecimal();
                    assertEquals(null, (BigDecimal) resf.result);
                    // test divide by 0
                    String[] zeroStrings = new String[] { "0", "-0", "0.0", "-0.0", "0.000000", "-0.000000" };
                    for (String zeroString : zeroStrings) {
                        lt.setValue(inpf1);
                        rt.setValue(new BigDecimal(zeroString));
                        resf = op.getNextBigDecimal();
                        assertEquals(null, (BigDecimal) resf.result);
                    }
                    break;
                }
            case DataType.DATETIME:
                DateTime inpdt1 = new DateTime(r.nextLong());
                DateTime inpdt2 = new DateTime(r.nextLong());
                lt.setValue(inpdt1);
                rt.setValue(inpdt2);
                Result resdt = op.getNextDateTime();
                assertEquals(resdt.returnStatus, POStatus.STATUS_ERR);
                // test with null in lhs
                lt.setValue(null);
                rt.setValue(inpdt2);
                resdt = op.getNextDateTime();
                assertEquals(resdt.returnStatus, POStatus.STATUS_ERR);
                // test with null in rhs
                lt.setValue(inpdt1);
                rt.setValue(null);
                resdt = op.getNextDateTime();
                assertEquals(resdt.returnStatus, POStatus.STATUS_ERR);
                break;
            case DataType.MAP:
                {
                    Map<String, Object> inpm1 = GenRandomData.genRandMap(r, 10);
                    Map<String, Object> inpm2 = GenRandomData.genRandMap(r, 10);
                    lt.setValue(inpm1);
                    rt.setValue(inpm2);
                    Result resm = op.getNextMap();
                    assertEquals(POStatus.STATUS_ERR, resm.returnStatus);
                    // test with null in lhs
                    lt.setValue(null);
                    rt.setValue(inpm2);
                    resm = op.getNextMap();
                    assertEquals(POStatus.STATUS_ERR, resm.returnStatus);
                    // test with null in rhs
                    lt.setValue(inpm1);
                    rt.setValue(null);
                    resm = op.getNextMap();
                    assertEquals(POStatus.STATUS_ERR, resm.returnStatus);
                    break;
                }
            case DataType.TUPLE:
                {
                    Tuple inpt1 = GenRandomData.genRandSmallBagTuple(r, 10, 100);
                    Tuple inpt2 = GenRandomData.genRandSmallBagTuple(r, 10, 100);
                    lt.setValue(inpt1);
                    rt.setValue(inpt2);
                    Result rest = op.getNextTuple();
                    assertEquals(POStatus.STATUS_ERR, rest.returnStatus);
                    // test with null in lhs
                    lt.setValue(null);
                    rt.setValue(inpt2);
                    rest = op.getNextTuple();
                    assertEquals(POStatus.STATUS_ERR, rest.returnStatus);
                    // test with null in rhs
                    lt.setValue(inpt1);
                    rt.setValue(null);
                    rest = op.getNextTuple();
                    assertEquals(POStatus.STATUS_ERR, rest.returnStatus);
                    break;
                }
        }
    }
