        for (Iterator<Tuple> bit = bg.iterator(); bit.hasNext(); ) {
            Tuple bt = bit.next();
            Assert.assertEquals(String.class, bt.get(0).getClass());
            Assert.assertEquals(String.class, bt.get(1).getClass());
        }
    }
    pigServer.deleteFile(output);
}

