    String[] types = new String[] { "left", "right", "full" };
    String[] joinTypes = new String[] { "replicated", "repl" };
    for (int i = 0; i < types.length; i++) {
        for (int j = 0; j < joinTypes.length; j++) {
            boolean errCaught = false;
