@Test
public void testQuery90a() throws Exception {
    LogicalPlan lp = null;
    LOForEach foreach = null;
    Operator store = null;
    String query = "a = load 'myfile' as (name:Chararray, age:Int, gpa:Float);" + "b = group a by (name, age);";
