    String testQuery = "a = load 'd.txt' as (id, v1, v2);" + "b = load 'd.txt' as (id, v1, v2);" + "c = distinct a;" + "d = union b, c;" + "e = foreach d generate id, v1;" + "store e into 'empty';";
