    assertEquals(1, ((POProject) prj5).getColumn());
    PhysicalOperator prj6 = ((POForEach) ForE).getInputPlans().get(1).getLeaves().get(0);
    assertEquals(POProject.class, prj6.getClass());
    assertEquals(2, ((POProject) prj6).getColumn());
    // Filter Operator
