@Test
public void testScopeOfParamWithNestedRunCommand() throws Exception {
    log.info("Starting test testScopeOfParamWithRunCommand()");
    File inputFile = Util.createFile("runinput", new String[] { "daniel\t10", "jenny\t20;" });
    /*
         * script1 sets a=1, b=2, c=3; calls script2
         *   script2 sets b=22 (by -param); calls script3
         *     script3 sets c=333; saves $a$b$c  (122333)
         *   script2 saves $a$b$c (1223)
         * script1 saves $a$b$c (123)
         */
    File script3 = Util.createFile("runscript3.pig", new String[] { "%declare c '333';", "a = load 'runinput';", "store a into 'testScopeOfParamWithNestedRunCommand${a}${b}${c}';" });
    File script2 = Util.createFile("runscript2.pig", new String[] { "run " + script3.getAbsolutePath() + ";", "a = load 'runinput';", "store a into 'testScopeOfParamWithNestedRunCommand${a}${b}${c}';" });
    File script1 = Util.createFile("runscript1.pig", new String[] { "%declare a '1';", "%declare b '2';", "%declare c '3';", "run -param b=22 " + script2.getAbsolutePath() + ";", "a = load 'runinput';", "store a into 'testScopeOfParamWithNestedRunCommand${a}${b}${c}';" });
    PigStats stats = org.apache.pig.PigRunner.run(new String[] { "-x", Util.getLocalTestMode().toString(), script1.getAbsolutePath() }, null);
    for (String output : stats.getOutputNames()) {
        assertTrue(output.contains("testScopeOfParamWithNestedRunCommand"));
        Util.deleteDirectory(new File(output));
    }
    assertTrue("job should succeed", stats.isSuccessful());
    assertEquals("There should be three outputs.", 3, stats.getOutputNames().size());
    for (String expectedoutput : new String[] { "testScopeOfParamWithNestedRunCommand123", "testScopeOfParamWithNestedRunCommand1223", "testScopeOfParamWithNestedRunCommand122333" }) {
        boolean found = false;
        for (String output : stats.getOutputNames()) {
            if (output.endsWith(expectedoutput)) {
                found = true;
            }
        }
        assertTrue("Output " + expectedoutput + " should exist.", found);
    }
}

