    Schema.FieldSchema bagFs1 = new Schema.FieldSchema("b", schema1, DataType.BAG);
    Schema bagSchema1 = new Schema(bagFs1);
    Schema.FieldSchema tupleFs = new Schema.FieldSchema("t", schema2, DataType.TUPLE);
