        String[] expectedD = { "(1,16.0)", "(2,8.0)" };
        Util.checkQueryOutputsAfterSortRecursive(iter, expectedD, org.apache.pig.newplan.logical.Util.translateSchema(s));
        iter = pigServer.openIterator("E");
        s = pigServer.dumpSchema("E");
