@Test
public void testMulitQueryWithSplitMultiVertex() throws Exception {
    String query = "a = load 'file:///tmp/input' as (x:int, y:int);" + "split a into b if x <= 5, c if x <= 10, d if x >10;" + "split b into e if x < 3, f if x >= 3;" + // No Combiner on the edge to b1/b2 vertex as both b1 and b2 are stored
    "b1 = group b by x;" + "b2 = foreach b1 generate group, SUM(b.x);" + // Case of two outputs within a split going to same edge as input
    "c1 = join c by x, b by x;" + "c2 = group c by x;" + // Combiner on the edge to c3 vertex
    "c3 = foreach c2 generate group, SUM(c.x);" + "d1 = filter d by x == 5;" + "e1 = order e by x;" + // TODO: Physical plan has extra split for f1 - 1-2: Split - scope-80
