@Test
public void testUnionIncludeExcludeStoreFunc() throws Exception {
    String query = "a = load 'file:///tmp/input' as (x:int, y:chararray);" + "b = load 'file:///tmp/input' as (y:chararray, x:int);" + "c = union onschema a, b;" + "store c into 'file:///tmp/pigoutput';";
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION, "" + true);
    String oldSupported = getProperty(PigConfiguration.PIG_TEZ_OPT_UNION_SUPPORTED_STOREFUNCS);
    String oldUnSupported = getProperty(PigConfiguration.PIG_TEZ_OPT_UNION_UNSUPPORTED_STOREFUNCS);
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION_UNSUPPORTED_STOREFUNCS, PigStorage.class.getName());
    // Plan should not have union optimization applied as PigStorage is unsupported
    run(query, "test/org/apache/pig/test/data/GoldenFiles/tez/TEZC-Union-1-OPTOFF.gld");
    resetScope();
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION_UNSUPPORTED_STOREFUNCS, null);
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION_SUPPORTED_STOREFUNCS, OrcStorage.class.getName());
    query = "a = load 'file:///tmp/input' as (x:int, y:chararray);" + "b = load 'file:///tmp/input' as (y:chararray, x:int);" + "c = union onschema a, b;" + "store c into 'file:///tmp/pigoutput' using " + TestDummyStoreFunc.class.getName() + "();";
    // Plan should not have union optimization applied as only ORC is supported
    run(query, "test/org/apache/pig/test/data/GoldenFiles/tez/TEZC-Union-1-DummyStore-OPTOFF.gld");
    resetScope();
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION_SUPPORTED_STOREFUNCS, null);
    query = "a = load 'file:///tmp/input' as (x:int, y:chararray);" + "b = load 'file:///tmp/input' as (y:chararray, x:int);" + "c = union onschema a, b;" + "store c into 'file:///tmp/pigoutput' using " + TestDummyStoreFuncParallelWriteDisabled.class.getName() + "();";
    // Plan should not have union optimization applied as supportsParallelWriteToStoreLocation returns false
    run(query, "test/org/apache/pig/test/data/GoldenFiles/tez/TEZC-Union-1-DummyStore2-OPTOFF.gld");
    resetScope();
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION_SUPPORTED_STOREFUNCS, null);
    query = "a = load 'file:///tmp/input' as (x:int, y:chararray);" + "b = load 'file:///tmp/input' as (y:chararray, x:int);" + "c = union onschema a, b;" + "store c into 'file:///tmp/pigoutput' using " + TestDummyStoreFuncParallelWriteEnabled.class.getName() + "();";
    // Plan should have union optimization applied as supportsParallelWriteToStoreLocation returns true
    run(query, "test/org/apache/pig/test/data/GoldenFiles/tez/TEZC-Union-1-DummyStore3.gld");
    resetScope();
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION_UNSUPPORTED_STOREFUNCS, PigStorage.class.getName());
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION_SUPPORTED_STOREFUNCS, null);
    query = "a = load 'file:///tmp/input' as (x:int, y:chararray);" + "split a into b if x > 5, c if x == 7, d if x == 8, e otherwise;" + "u1 = union onschema b, c;" + "store u1 into 'file:///tmp/pigoutput/u1';" + //TODO: multiple levels of split not merged
    "u2 = union onschema a, b, c;" + "store u2 into 'file:///tmp/pigoutput/u2';" + "u3 = union onschema d, e;" + "store u3 into 'file:///tmp/pigoutput/u3';" + "j1 = join d by x, a by x using 'replicated';" + "j1 = foreach j1 generate d::x as x, d::y as y;" + "u4 = union onschema j1, a;" + "store u4 into 'file:///tmp/pigoutput/u4';";
    // Plan should have union optimization applied even for unsupported storefunc
    run(query, "test/org/apache/pig/test/data/GoldenFiles/tez/TEZC-Union-1-SplitStore.gld");
    // Restore the value
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION_SUPPORTED_STOREFUNCS, oldSupported);
    setProperty(PigConfiguration.PIG_TEZ_OPT_UNION_UNSUPPORTED_STOREFUNCS, oldUnSupported);
}

