@Test
public void testRun3() throws Exception {
    String query = "a = load '" + input1 + "' as (x:int, y:int);" + "b = load '" + input2 + "' as (x:int, z:int);" + "c = join a by x, b by x;" + "d = foreach c generate a::x as x, y, z;" + "store d into 'file:///tmp/pigoutput';";
