    assertNotNull(leaf);
    assertEquals(2, leaf.getInputVertices().size());
    assertEquals(0, leaf.getOutputVertices().size());
    assertEquals(root0.getOutputVertices().get(0), leaf);
    assertEquals(root1.getOutputVertices().get(0), leaf);
