@Test
public void testDAGDiscoveryDisabled() throws IOException {
    String output1 = TEST_DIR + Path.SEPARATOR + "output-parallel";
    String output2 = TEST_DIR + Path.SEPARATOR + "output-autoparallel";
    String scriptFile = TEST_DIR + Path.SEPARATOR + "testDAGRecoveryDisable.pig";
    String query = "A = LOAD '" + INPUT_FILE + "';" + "B = GROUP A BY $0 PARALLEL 1;" + "STORE B into '" + output1 + "';" + "exec;" + "C = LOAD '" + INPUT_FILE + "';" + "D = GROUP C BY $0;" + "STORE D into '" + output2 + "';";
    Util.createLocalInputFile(scriptFile, new String[] { query });
    String[] args = { "-x", "tez_local", scriptFile };
    TestNotificationListener listener = new TestNotificationListener();
    // Recovery is not disabled when there is auto parallelism. Should reuse AM application session
    PigStats stats = PigRunner.run(args, listener);
    assertTrue(stats.isSuccessful());
    assertEquals(1, listener.getJobsStarted().size());
    Util.deleteFile(pigServer.getPigContext(), output1);
    Util.deleteFile(pigServer.getPigContext(), output2);
    // Recovery is disabled when there is auto parallelism. Should use two different AMs
    listener.reset();
    args = new String[] { "-D" + PigConfiguration.PIG_TEZ_AUTO_PARALLELISM_DISABLE_DAG_RECOVERY + "=true", "-x", "tez_local", scriptFile };
    stats = PigRunner.run(args, listener);
    assertTrue(stats.isSuccessful());
    assertEquals(2, listener.getJobsStarted().size());
}

@Test
public void testRun1() throws Exception {
    String query = "a = load '" + INPUT_FILE + "' as (x:int, y:chararray);" + "b = filter a by x > 100;" + "c = foreach b generate y;" + "d = group c all;" + "store d into '" + OUTPUT_FILE + "';";
    PhysicalPlan pp = Util.buildPp(pigServer, query);
    TezLauncher launcher = new TezLauncher();
    PigStats pigStats = launcher.launchPig(pp, "testRun1", pc);
    assertTrue(pigStats.isSuccessful());
    assertEquals(1, pigStats.getInputStats().size());
    assertEquals(INPUT_FILE, pigStats.getInputStats().get(0).getName());
    assertEquals(1, pigStats.getOutputStats().size());
    assertEquals(OUTPUT_FILE, pigStats.getOutputStats().get(0).getName());
    query = "m = load '" + OUTPUT_FILE + "' as (a:chararray, b:{(y:chararray)});";
    pigServer = new PigServer(pc);
    pigServer.registerQuery(query);
    Iterator<Tuple> iter = pigServer.openIterator("m");
    Tuple result = iter.next();
    assertEquals(result.get(0).toString(), "all");
    Iterator<Tuple> innerIter = ((DataBag) result.get(1)).iterator();
    int count = 0;
    while (innerIter.hasNext()) {
        assertTrue(Arrays.asList(OUTPUT_RECORDS).contains(innerIter.next().toString()));
        count++;
    }
    assertEquals(count, OUTPUT_RECORDS.length);
}

