}

@Test
public void testProcessShellCmdBigStderr() throws ParameterSubstitutionException, FrontendException {
    // This test probably doesn't work on Windows, but should work elsewhere
    Assume.assumeFalse(Shell.WINDOWS);
    PreprocessorContext ctx = new PreprocessorContext(0);
    String cmd = "bash -c 'i=0; while [ \"\\$i\" -lt 10000 ]; do echo long-stderr-output >&2; " + "i=\\$((i+1)); done; echo hello'";
    ctx.processShellCmd("some_value", "`" + cmd + "`");
    Map<String, String> paramVal = ctx.getParamVal();
    assertEquals("hello", paramVal.get("some_value"));
}

@Test
public void testFailingCommand() throws ParameterSubstitutionException, FrontendException {
    try {
        PreprocessorContext ctx = new PreprocessorContext(0);
        String cmd = "exit 1";
        ctx.processShellCmd("some_value", "`" + cmd + "`");
    } catch (RuntimeException e) {
        assertTrue(Pattern.compile("Error executing shell command:.*exit code.*").matcher(e.getMessage()).matches());
    }
}

@Test
public void testEscaping() throws ParameterSubstitutionException, FrontendException {
    PreprocessorContext ctx = new PreprocessorContext(0);
    // quote argument to echo so that the shell doesn't treat the backslash as an escape and consume it
    String cmd = "echo '$\\stuff'";
    ctx.processShellCmd("some_value", "`" + cmd + "`");
    String subVal = ctx.substitute("$some_value");
    assertEquals("$\\stuff", subVal);
}
